input.sparql:
SELECT ?point ?ts_id WHERE {
  ?point brick:hasProperty ?p .
  ?point ref:hasTimeseriesId ?ts_id .
  FILTER(?p = "electricity" || ?p = "power" || ?p = "energy")
}
LIMIT 20

SELECT ?point ?ts_id WHERE {
  ?point a brick:Electric_Power_Sensor .
  ?point ref:hasTimeseriesId ?ts_id .
}
LIMIT 200
